SR = 16_000
WIN_MS = 25
HOP_MS = 10
N_MFCC = 26
N_CONTEXT = 9


def window_samples(sample_rate=SR):
    return int(sample_rate * WIN_MS / 1000)


def hop_samples(sample_rate=SR):
    return int(sample_rate * HOP_MS / 1000)


def n_frames(num_samples, sample_rate=SR):
    window = window_samples(sample_rate)
    hop = hop_samples(sample_rate)
    if num_samples < window:
        return 0
    return 1 + (num_samples - window) // hop


def input_width():
    return (2 * N_CONTEXT + 1) * N_MFCC


def check_audio(sample_rate, channels, dtype):
    if sample_rate != SR:
        raise ValueError(f"audio must be {SR} Hz, got {sample_rate}")
    if channels != 1:
        raise ValueError(f"audio must be mono, got {channels} channels")
    if dtype != "int16":
        raise ValueError(f"audio must be int16 samples, got {dtype}")
    return True


def wer_counts(reference, hypothesis):
    ref = reference.split()
    hyp = hypothesis.split()
    if not ref:
        raise ValueError("the reference must contain at least one word")

    rows = len(ref) + 1
    cols = len(hyp) + 1
    cost = [[0] * cols for _ in range(rows)]
    back = [[None] * cols for _ in range(rows)]
    for i in range(1, rows):
        cost[i][0] = i
        back[i][0] = "deletion"
    for j in range(1, cols):
        cost[0][j] = j
        back[0][j] = "insertion"
    for i in range(1, rows):
        for j in range(1, cols):
            if ref[i - 1] == hyp[j - 1]:
                cost[i][j] = cost[i - 1][j - 1]
                back[i][j] = "match"
                continue
            options = ((cost[i - 1][j - 1] + 1, "substitution"),
                       (cost[i][j - 1] + 1, "insertion"),
                       (cost[i - 1][j] + 1, "deletion"))
            cost[i][j], back[i][j] = min(options, key=lambda option: option[0])

    counts = {"substitutions": 0, "insertions": 0, "deletions": 0}
    i, j = len(ref), len(hyp)
    while i > 0 or j > 0:
        action = back[i][j]
        if action == "match":
            i, j = i - 1, j - 1
        elif action == "substitution":
            counts["substitutions"] += 1
            i, j = i - 1, j - 1
        elif action == "insertion":
            counts["insertions"] += 1
            j -= 1
        else:
            counts["deletions"] += 1
            i -= 1
    counts["reference_words"] = len(ref)
    return counts


def wer(reference, hypothesis):
    counts = wer_counts(reference, hypothesis)
    errors = (counts["substitutions"] + counts["insertions"]
              + counts["deletions"])
    return errors / counts["reference_words"]
